// index.js
// Express application entry point.
// The server should only start listening when this file is executed directly.
// This allows test suites (e.g., using supertest) to import the app without
// causing an "EADDRINUSE" error caused by multiple listeners on the same port.

const express = require('express');
const app = express();

// Middleware / routes
app.get('/hello', (req, res) => {
  res.json({ message: 'Hello World' });
});

// Port configuration – default to 3000 for local development.
const PORT = process.env.PORT || 3000;

// Only start the HTTP server when this module is the entry point.
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server listening on port ${PORT}`);
  });
}

// Export the Express app for testing or external usage.
module.exports = app;
